import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { openDatabase } from './db.ts';
import { WORKER_STALE_MS, parseSubmission, toJobJson, type FieldError, type JobRow, type Submission } from './jobs.ts';

const MAX_BODY_BYTES = 64 * 1024;

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

const stmts = {
  byId: db.prepare('SELECT * FROM jobs WHERE id = ?'),
  byKey: db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?'),
  list: db.prepare('SELECT * FROM jobs ORDER BY seq DESC'),
  insert: db.prepare(
    `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, completed, run_after, lease_until,
                       idempotency_key, request_fingerprint, created_at, updated_at)
     VALUES (?, 'queued', ?, ?, ?, 0, 0, 0, 0, ?, ?, ?, ?)`,
  ),
  workerHeartbeat: db.prepare("SELECT at FROM heartbeats WHERE name = 'worker'"),
};

function send(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...headers });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[], headers?: Record<string, string>): void {
  send(res, status, { error: fields ? { code, message, fields } : { code, message } }, headers);
}

const notFound = (res: ServerResponse) => sendError(res, 404, 'not_found', 'No such resource.');
const notAllowed = (res: ServerResponse, allow: string) => sendError(res, 405, 'method_not_allowed', 'Method not allowed.', undefined, { allow });

function readBody(req: IncomingMessage): Promise<string | undefined> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => resolve(tooLarge ? undefined : Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

type SubmitOutcome = { kind: 'created' | 'replayed'; job: JobRow } | { kind: 'conflict' };

/** Inserts the job, or finds the earlier job for the same Idempotency-Key. Runs in one write transaction. */
function submit(submission: Submission, idempotencyKey: string | undefined): SubmitOutcome {
  const fingerprint = JSON.stringify([submission.input, submission.steps, submission.failAttempts]);
  db.exec('BEGIN IMMEDIATE');
  try {
    if (idempotencyKey !== undefined) {
      const existing = stmts.byKey.get(idempotencyKey) as unknown as JobRow | undefined;
      if (existing) {
        db.exec('COMMIT');
        return existing.request_fingerprint === fingerprint ? { kind: 'replayed', job: existing } : { kind: 'conflict' };
      }
    }
    const now = new Date().toISOString();
    const id = randomUUID();
    stmts.insert.run(id, submission.input, submission.steps, submission.failAttempts, idempotencyKey ?? null, fingerprint, now, now);
    const job = stmts.byId.get(id) as unknown as JobRow;
    db.exec('COMMIT');
    return { kind: 'created', job };
  } catch (e) {
    try {
      db.exec('ROLLBACK');
    } catch {
      // no transaction was open
    }
    throw e;
  }
}

async function handlePostJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const raw = await readBody(req);
  const header = req.headers['idempotency-key'];
  const parsed = parseSubmission(req.headers['content-type'], raw, typeof header === 'string' ? header : undefined);
  if (!parsed.ok) {
    sendError(res, 400, 'invalid_request', 'The request is invalid.', parsed.fields);
    return;
  }
  const outcome = submit(parsed.submission, parsed.idempotencyKey);
  if (outcome.kind === 'conflict') {
    sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
    return;
  }
  send(res, outcome.kind === 'created' ? 201 : 200, toJobJson(outcome.job));
}

function handleHealth(res: ServerResponse): void {
  const hb = stmts.workerHeartbeat.get() as { at: number } | undefined;
  const up = hb !== undefined && Date.now() - Number(hb.at) <= WORKER_STALE_MS;
  send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
}

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const method = req.method ?? 'GET';
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');

  if (pathname === '/health') {
    if (method !== 'GET') return notAllowed(res, 'GET');
    return handleHealth(res);
  }
  if (pathname === '/') {
    if (method !== 'GET') return notAllowed(res, 'GET');
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }
  if (pathname === '/api/jobs') {
    if (method === 'GET') {
      const rows = stmts.list.all() as unknown as JobRow[];
      return send(res, 200, { jobs: rows.map(toJobJson) });
    }
    if (method === 'POST') return handlePostJob(req, res);
    return notAllowed(res, 'GET, POST');
  }
  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match) {
    if (method !== 'GET') return notAllowed(res, 'GET');
    let id: string;
    try {
      id = decodeURIComponent(match[1]!);
    } catch {
      return notFound(res);
    }
    const row = stmts.byId.get(id) as unknown as JobRow | undefined;
    if (!row) return notFound(res);
    return send(res, 200, toJobJson(row));
  }
  notFound(res);
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  handle(req, res).catch((e: unknown) => {
    console.error('request failed:', e);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
    else res.end();
  });
});

server.listen(port, () => console.log(`server listening on ${port}`));

let stopping = false;
function shutdown(): void {
  if (stopping) return;
  stopping = true;
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeIdleConnections();
  setTimeout(() => server.closeAllConnections(), 1_000).unref();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

